THOUGHT: The patient has two magnesium levels recorded today. The first is 2.2 mg/dL and the second is 0.8 mg/dL. Since 0.8 mg/dL is below 1 mg/dL (severe deficiency), I will order 4g of IV magnesium over 4 hours. I will now create a MedicationRequest for this.
POST http://localhost:8080/fhir/MedicationRequest
{
  "resourceType": "MedicationRequest",
  "medicationCodeableConcept": {
    "coding": [
      {
        "system": "http://hl7.org/fhir/sid/ndc",
        "code": "0338-1715-40",
        "display": "Magnesium Chloride Injection"
      }
    ],
    "text": "IV Magnesium"
  },
  "authoredOn": "2023-11-13T10:15:00+00:00",
  "dosageInstruction": [
    {
      "route": {
        "text": "IV"
      },
      "doseAndRate": [
        {
          "doseQuantity": {
            "value": 4,
            "unit": "g"
          }
        }
      ],
      "timing": {
        "repeat": {
          "boundsDuration": "4h"
        }
      }
    }
  ],
  "status": "active",
  "intent": "order",
  "subject": {
    "reference": "Patient/S3236936"
  }
}
FINISH(["4g IV magnesium over 4 hours ordered for patient S3236936"])

